// The permission matrix (docs/PERMISSIONS.md §4), as frozen data. Card 35, CASE-168, CASE-336, CASE-337.
//
// docs/PERMISSIONS.md is the source. tests/permissions-matrix.test.mjs parses its marked §4 table and
// fails on any difference from this module, and the SQL role table (case_app.action_roles, action_case_roles,
// policy_allows, generated by scripts/gen-permissions.mjs) is checked against this module, so the doc, the
// Worker and the database cannot drift. Pure data and pure functions: no I/O, nothing read from a request.
//
// Cells: yes · step (a fresh scoped step-up) · own (a room the principal started) · cap (holder of that
// room capability; P-46: of the invitation reference) · pol (refused unless the row's workspace policy is
// on) · own+pol (own, and every room in the workspace when the policy is on) · no.
//
// Access = person × place × level (CASE-336). A place is a workspace or one case. The workspace columns are
// owner (Can manage), author (Can edit) and facilitator (Can run); caseAuthor and caseFacilitator are a
// grant of Can edit or Can run on ONE case, and describe what that grant gives on that case only. Can manage
// is never a case grant. On a case the person holds the strongest cell of every column they hold there.

export const PRINCIPALS = Object.freeze(['admin', 'owner', 'author', 'facilitator', 'caseAuthor', 'caseFacilitator',
  'participant', 'projector', 'sharedPc']);
export const CELLS = Object.freeze(['yes', 'step', 'own', 'cap', 'pol', 'own+pol', 'no']);
/** Workspace roles, strongest first (owner ⊇ author ⊇ facilitator). */
export const WORKSPACE_ROLES = Object.freeze(['owner', 'author', 'facilitator']);
/** Case grant level → its matrix column. Can manage is workspace-only, so there is no `manage` level. */
export const CASE_GRANT_LEVELS = Object.freeze({ edit: 'caseAuthor', run: 'caseFacilitator' });
/** Each case column mirrors the workspace role of the same level (§4.3): its cell is that role's, or `no`. */
export const CASE_MIRROR = Object.freeze({ caseAuthor: 'author', caseFacilitator: 'facilitator' });

/**
 * The four per-workspace policies with their defaults (CASE-337), set by administrators (P-45). Every
 * existing workspace gets these defaults when the policies table lands, "managers see records" included.
 */
export const POLICIES = Object.freeze({
  managers_invite: true,
  editors_publish: false,
  runners_share: false,
  managers_see_records: true,
});
/** The policy behind each row that has a `pol` or `own+pol` cell (docs/PERMISSIONS.md §4.3). One per row. */
