/**
 * Rows whose action a later card (a number) or facilitator-UX step (`A4`) ships; the matrix test reports them
 * `todo` with that card or step.
 */
export const LATER = Object.freeze({ 'P-02': 31, 'P-16': 32, 'P-17': 32 });

/** Cells that grant without a policy (own+pol always grants at least own). */
const GRANTS = new Set(['yes', 'step', 'own', 'own+pol']);
const POLICY_CELLS = new Set(['pol', 'own+pol']);

/** The cell for (action id, principal); throws on an unknown id or principal (a programming error). */
export function cell(id, principal) {
  if (!Object.hasOwn(MATRIX, id) || !PRINCIPALS.includes(principal)) throw new TypeError(`unknown permission ${id}/${principal}`);
  return MATRIX[id][principal];
}

/** The workspace roles a row grants whatever the policies (yes, step, own, own+pol), strongest first. Drives the SQL role table. */
export function rolesFor(id) {
  return WORKSPACE_ROLES.filter(role => GRANTS.has(cell(id, role)));
}

/** The roles (author, facilitator) a case grant of that level reaches on its own case, whatever the policies. */
export function caseRolesFor(id) {
  return Object.entries(CASE_MIRROR).filter(([column]) => GRANTS.has(cell(id, column))).map(([, role]) => role);
}

/** The workspace roles whose cell on this row is `pol` or `own+pol`, strongest first. Drives case_app.policy_allows. */
export function policyRolesFor(id) {
  return WORKSPACE_ROLES.filter(role => POLICY_CELLS.has(cell(id, role)));
}

/** Whether a policy is on in a workspace's policy object. Only a literal `true` is on; anything else fails closed. */
export function policyOn(policies, key) {
  return Object.hasOwn(POLICIES, key) && policies != null && Object.hasOwn(policies, key) && policies[key] === true;
}

/** The cell after the workspace's policies apply: `pol` → yes/no, `own+pol` → yes/own; other cells unchanged. */
export function resolveCell(id, principal, policies) {
  const value = cell(id, principal);
  if (!POLICY_CELLS.has(value)) return value;
  const on = policyOn(policies, POLICY_OF[id]);
  return value === 'pol' ? (on ? 'yes' : 'no') : (on ? 'yes' : 'own');
}

const RANK = Object.freeze({ owner: 3, author: 2, facilitator: 1 });
const GRANT_ROLE = Object.freeze({ edit: 'author', run: 'facilitator' });

/**
 * The highest level a person holds on one case (CASE-336), as the SQL `case_app.effective_role` returns it:
 * `{ role, scope }` in the existing vocabulary, scope `workspace` or `case`; a tie keeps the workspace. `grant`
 * is the person's live grant on THIS case (`edit` | `run`), never another case's. Null when they hold neither.
 */
export function effectiveLevel({ role = null, grant = null } = {}) {
  if (role !== null && !WORKSPACE_ROLES.includes(role)) throw new TypeError(`unknown workspace role ${role}`);
  if (grant !== null && !Object.hasOwn(GRANT_ROLE, grant)) throw new TypeError(`unknown case grant ${grant}`);
  const fromGrant = grant === null ? null : GRANT_ROLE[grant];
  if (role === null && fromGrant === null) return null;
  if (fromGrant !== null && (role === null || RANK[fromGrant] > RANK[role])) return { role: fromGrant, scope: 'case' };
  return { role, scope: 'workspace' };
}

const STRENGTH = Object.freeze({ yes: 4, step: 3, own: 2, cap: 1, no: 0 });

/**
 * What one person may do for a row, after policies: the strongest resolved cell of every column they hold.
 * `role` is their workspace role, `grant` their grant on the case the request names (null for a workspace
 * action, or when they hold none on that case). A grant on another case must never be passed: it reaches
 * nothing here. The admin path is the admin column alone.
 */
export function decide(id, { admin = false, role = null, grant = null } = {}, policies) {
  if (admin) return resolveCell(id, 'admin', policies);
  effectiveLevel({ role, grant }); // validates role and grant
  const held = [];
  if (role !== null) held.push(resolveCell(id, role, policies));
  if (grant !== null) held.push(resolveCell(id, CASE_GRANT_LEVELS[grant], policies));
  return held.reduce((best, next) => (STRENGTH[next] > STRENGTH[best] ? next : best), 'no');
}

/** Whether an admin (a verified ADMIN_EMAILS identity) reaches this row at all, with or without step-up. */
export function adminReaches(id) {
  return GRANTS.has(cell(id, 'admin'));
}

/** Whether this row needs a fresh scoped step-up for the given principal. */
export function needsStepUp(id, principal) {
  return cell(id, principal) === 'step';
}

/** The actions the SQL core (case_app.authorize) knows: every row with an R enforcement point. */
